    'landing.sec5OpenStudio': 'Open Vernacular Audio-Rx Studio',
    'landing.sec6Title': 'Prototype Safety Boundaries: Clinician Review & Open Reference Formats',
    'landing.sec6Subtitle': 'Healthcare AI requires clear limits, privacy disclosure, and human review. Explore the prototype safety boundaries and local FHIR-shaped draft checks below.',
    'landing.sec6TabGovernance': '1. Doctor-in-the-Loop Governance (4 Safeguards)',
    'landing.sec6TabStandards': '2. Academic Rigor & Open Standards (6 Benchmarks)',
    'faq.headerTag': 'FREQUENTLY ASKED QUESTIONS',
    'faq.mainHeading': 'Everything You Need to Know About AyuSwar AI',
    'faq.supportCardTag': '24/7 VIRTUAL CLINICAL SUPPORT',
    'faq.supportCardTitle': 'Have Questions? We Have Answers.',
    'faq.supportCardDesc': 'Explore the prototype safeguards for noisy OPD capture, speech playback, and local review; full DPDP compliance and live WhatsApp delivery are not claimed.',
    'faq.q1': 'Does AyuSwar replace doctors?',
    'faq.a1': 'Absolutely not. AyuSwar AI is an ambient documentation co-pilot prototype. Generated notes, codes, and prescription text remain structured drafts for clinician review and local acknowledgement; no Class-3 DSC signing or ABDM commitment is connected.',
    'faq.q2': 'How is patient data protected?',
    'faq.a2': 'This public build is a synthetic-data research prototype. It is not presented as fully DPDP-compliant or deployed on a verified sovereign clinical cloud. Raw microphone capture, external processing, retention, encryption, and access controls are disclosed per feature instead of implied.',
    'faq.q3': 'Does it work with code-mixed speech (e.g., Telugu + English / Tenglish)?',
    'faq.a3': 'Yes. Indian clinical consultations rarely happen in pure textbook languages. AyuSwar prototype uses browser speech recognition with planned Indic voice integration, designed to decode code-mixed Telugu, Hindi, Tamil, Kannada, and "Tenglish/Hinglish" where clinical terms (like "sugar", "BP", "inhaler", "fever") blend naturally with vernacular grammar.',
    'faq.q4': 'How does it handle noisy environments?',
    'faq.a4': 'AyuSwar features an adaptive WebAudio 16 kHz AudioWorklet dual-channel DSP front-end with spectral noise subtraction. It filters out ceiling fan hums, corridor chatter, and adjacent murmur in rural OPD waiting halls to assist speech capture.',
    'faq.q5': 'How does the clinician verify AI-generated information?',
    'faq.a5': 'The doctor console presents extracted consultation fields for review and editing before demo acknowledgement. The visible workflow keeps the clinician in control; it does not issue an official e-Prescription.',
    'faq.q6': 'How does ABDM/FHIR integration work?',
    'faq.a6': 'The current build generates a local FHIR-shaped research draft for inspection. It does not verify ABHA numbers, connect to ABDM milestones, apply a DSC signature, or dispatch records to the national health exchange.',
    'faq.q7': 'What happens when the AI is uncertain?',
    'faq.a7': 'AyuSwar utilizes probabilistic uncertainty thresholding. If acoustic noise obscures a sentence or phoneme confidence drops below 85%, the system never hallucinates or guesses. Instead, it flags the phrase in amber with an explicit "Requires Doctor Clarification" tag and prompts the clinician to confirm before generating prescription orders.',
    'faq.q8': 'Can patients receive spoken audio instructions in their own language?',
    'faq.a8': 'The Audio-Rx studio can draft clear spoken dosage instructions with color-coded pill reminders in Telugu, Hindi, or English. Playback depends on the available speech path; WhatsApp delivery is not connected.',
    'faq.q9': 'How does Jan Aushadhi generic substitution assist patients?',
    'faq.a9': 'When an outpatient prescription or medicine strip is scanned, AyuSwar compares extracted text with a bundled Jan Aushadhi-inspired sample formulary. Possible generic labels are for review; savings are sample-basket estimates, not live price or eligibility evidence.',
    'faq.q10': 'What devices and browsers are supported?',
    'faq.a10': 'AyuSwar is built as a lightweight progressive web application (PWA). It runs smoothly across Chrome, Edge, Safari, and Firefox on basic Android smartphones, clinic tablets, and rural PHC desktops without requiring specialized hardware.',
    'faq.q11': 'Can clinicians edit or override AI suggestions before signing?',
