    'landing.sec5Title': 'ఇంటరాక్టివ్ మాండలిక అట్లాస్ & కచేరీ స్క్రబ్బర్',
    'landing.sec5Subtitle': 'నమూనా కరోకే ఆడియోను చూడండి. ఇది సమీక్ష మరియు షేరింగ్‌కు సహాయపడే లక్షణం; మందుల భద్రతను నిరూపించదు.',
