    'faq.headerTag': 'अक्सर पूछे जाने वाले प्रश्न',
    'faq.mainHeading': 'आयुस्वर एआई के बारे में वह सब कुछ जो आपको जानना चाहिए',
    'faq.supportCardTag': '24/7 वर्चुअल क्लिनिकल सहायता',
    'faq.supportCardTitle': 'क्या आपके कोई प्रश्न हैं? हमारे पास उत्तर हैं।',
    'faq.supportCardDesc': 'OPD शोर, speech playback और local review workflow के लिए बने prototype परीक्षण देखें; पूर्ण DPDP compliance या live WhatsApp delivery का दावा नहीं किया जाता.',
    'faq.q1': 'क्या आयुस्वर डॉक्टरों की जगह लेता है?',
    'faq.a1': 'बिल्कुल नहीं। आयुस्वर एआई एक ambient documentation co-pilot prototype है. AI notes, codes और prescription text clinician review के लिए draft हैं; Class-3 DSC signing या ABDM commitment कनेक्ट नहीं है.',
    'faq.q2': 'मरीज का डेटा कैसे सुरक्षित रहता है?',
    'faq.a2': 'यह synthetic-data research prototype है. हम पूर्ण DPDP compliance, verified sovereign cloud, या सभी raw audio की RAM-only processing का साक्ष्य-रहित दावा नहीं करते. हर feature की वर्तमान सीमा उसी के साथ दिखाई जाती है.',
    'faq.q3': 'क्या यह हिंग्लिश और कोड-मिक्स्ड भाषा समझता है?',
    'faq.a3': 'हाँ, भारत में ओपीडी परामर्श अक्सर मिश्रित भाषाओं में होते हैं। आयुस्वर हिंदी, अंग्रेजी और स्थानीय बोलियों के प्राकृतिक मिश्रण को समझता है।',
    'faq.q4': 'यह शोरगुल वाले वातावरण को कैसे संभालता है?',
    'faq.a4': 'आयुस्वर में 16 kHz ऑडियो डीएसपी तकनीक है जो पंखों और गलियारे के शोर को हटाकर केवल डॉक्टर-मरीज की आवाज़ पर ध्यान केंद्रित करती है।',
    'faq.q5': 'चिकित्सक एआई सुझावों का सत्यापन कैसे करते हैं?',
    'faq.a5': 'डॉक्टर कंसोल AI द्वारा बनाई गई जानकारी को समीक्षा और संपादन के लिए दिखाता है. डेमो acknowledgement के बाद भी यह आधिकारिक e-Prescription नहीं है.',
    'faq.q6': 'ABDM/FHIR एकीकरण कैसे काम करता है?',
    'faq.a6': 'वर्तमान बिल्ड केवल स्थानीय FHIR-आकार का research draft बनाता है. यह ABHA सत्यापन, ABDM कनेक्शन, DSC हस्ताक्षर या राष्ट्रीय exchange dispatch नहीं करता.',
    'faq.q7': 'जब एआई अनिश्चित होता है तो क्या होता है?',
    'faq.a7': 'यदि विश्वास स्तर 85% से कम होता है, तो प्रणाली कभी अनुमान नहीं लगाती। इसके बजाय, यह पीले रंग में "डॉक्टर स्पष्टीकरण आवश्यक" टैग दिखाती है।',
    'faq.q8': 'क्या मरीजों को उनकी अपनी भाषा में बोले जाने वाले निर्देश मिल सकते हैं?',
    'faq.a8': 'ऑडियो-आरएक्स स्टूडियो हिंदी, तेलुगु या अंग्रेजी में रंग-कोडित बोली जाने वाली दवा सूचनाएं बना सकता है. प्लेबैक उपलब्ध speech path पर निर्भर है; WhatsApp delivery कनेक्ट नहीं है.',
    'faq.q9': 'जन औषधि योजना मरीजों की कैसे मदद करती है?',
    'faq.a9': 'दवा पर्ची स्कैन करने पर, आयुस्वर bundled sample formulary से संभावित generic labels दिखाता है। बचत sample prices पर आधारित है; live कीमत या पात्रता की गारंटी नहीं।',
    'faq.q10': 'कौन से उपकरण और ब्राउज़र समर्थित हैं?',
    'faq.a10': 'आयुस्वर एक हल्का प्रोग्रेसिव वेब ऐप (PWA) है जो बुनियादी एंड्रॉइड फोन, टैबलेट और कंप्यूटर पर क्रोम और एज में सुचारू रूप से चलता है।',
    'faq.q11': 'क्या डॉक्टर हस्ताक्षर से पहले बदलाव कर सकते हैं?',
    'faq.a11': 'हमेशा। डॉक्टर की स्पष्ट समीक्षा और डिजिटल हस्ताक्षर के बिना कुछ भी अंतिम रूप से रिकॉर्ड में दर्ज नहीं होता।',
    'footer.tagline': 'भारत के लिए एम्बिएंट क्लिनिकल वॉयस ऑपरेटिंग सिस्टम। डॉक्टर के दस्तावेज़ीकरण तनाव और मरीजों की भाषा बाधा को दूर करता है।',
    'footer.architecture': 'सिंथेटिक भारतीय क्लिनिकल वॉयस प्रोटोटाइप आर्किटेक्चर।',
